    for c0 in (0, 4):
        for r0 in range(0, h - 2, 4):
            cells = [(dr, dc, grid[r0 + dr][c0 + dc])
                     for dr in range(3) for dc in range(3)
                     if grid[r0 + dr][c0 + dc] != 0]
            if not cells:
                continue
            color = cells[0][2]
            mask = {(dr, dc) for dr, dc, _ in cells}
            if mask == {(0,0),(0,1),(1,0),(1,2),(2,1)}:   # east, 3 cells
                glyphs.append((color, 'E', 3))
            elif mask == {(0,0),(0,2),(1,0),(1,2),(2,0),(2,1),(2,2)}: # west, 2
                glyphs.append((color, 'W', 2))
            elif mask == {(0,0),(0,2),(1,1),(2,1)}:       # south, 2
                glyphs.append((color, 'S', 2))
            elif mask == {(0,0),(0,1),(0,2),(1,1),(2,0),(2,2)}: # west, 4
                glyphs.append((color, 'W', 4))
            else:
